    subject_id BINARY(16) NOT NULL,
    workflow_id BINARY(16) NULL,
    workflow_service_identity_id BINARY(16) NULL,
    primary_resource_type VARCHAR(32) NOT NULL,
    primary_resource_id BINARY(16) NOT NULL,
    primary_resource_version_id BINARY(16) NULL,
    operation_key VARCHAR(32) NOT NULL,
    source_node_id VARCHAR(128) NULL,
    source_revision BIGINT UNSIGNED NULL,
    source_draft_id BINARY(16) NULL,
    request_message VARCHAR(1000) NULL,
    dependency_hash VARCHAR(80) NOT NULL,
    open_dedupe_key VARCHAR(80) NULL,
    status ENUM('pending', 'approved', 'rejected', 'cancelled', 'stale') NOT NULL DEFAULT 'pending',
    requested_by BINARY(16) NOT NULL,
    resolved_at TIMESTAMP(6) NULL,
    version BIGINT UNSIGNED NOT NULL DEFAULT 1,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_resource_grant_request_open (tenant_id, open_dedupe_key),
    KEY idx_resource_grant_request_inbox (tenant_id, status, updated_at),
    KEY idx_resource_grant_request_subject (tenant_id, subject_type, subject_id, status),
    KEY idx_resource_grant_request_workflow (tenant_id, workflow_id, status),
    CONSTRAINT chk_resource_grant_request_subject CHECK (
        (subject_type = 'workflow_service_identity' AND workflow_id IS NOT NULL AND workflow_service_identity_id = subject_id)
        OR (subject_type = 'department' AND workflow_id IS NULL AND workflow_service_identity_id IS NULL)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE resource_grants (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    subject_type ENUM('department', 'workflow_service_identity') NOT NULL,
    subject_id BINARY(16) NOT NULL,
    resource_type VARCHAR(32) NOT NULL,
    resource_id BINARY(16) NOT NULL,
    resource_version_id BINARY(16) NULL,
    operation_key ENUM('view', 'use', 'read', 'write', 'manage') NOT NULL,
    created_by BINARY(16) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_resource_grant (tenant_id, subject_type, subject_id, resource_type, resource_id, operation_key),
    KEY idx_resource_grant_resource (tenant_id, resource_type, resource_id),
    KEY idx_resource_grant_subject (tenant_id, subject_type, subject_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE resource_health_checks (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    resource_type VARCHAR(32) NOT NULL,
    resource_id BINARY(16) NOT NULL,
    check_sequence BIGINT UNSIGNED NOT NULL,
    status ENUM('healthy', 'unhealthy', 'unsupported') NOT NULL,
    latency_ms BIGINT UNSIGNED NULL,
    error_code VARCHAR(128) NULL,
    error_message VARCHAR(512) NULL,
    checked_by BINARY(16) NOT NULL,
    checked_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_resource_health_sequence (tenant_id, resource_type, resource_id, check_sequence),
    KEY idx_resource_health_latest (tenant_id, resource_type, resource_id, checked_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE retention_items (
